SEED_DAYS = 30
SEED_CAP = 300  # same as origin.services.task_recents.RECENT_TASKS_CAP


def seed_from_own_edits(apps, schema_editor):
    """Start each person's Recents from what they did in the last 30 days.

    Opens were never recorded, so without this the list would be empty until
    every task is opened again. A person's own audit rows are the closest thing:
    one row per (person, task), stamped with their latest edit, newest first,
    at most SEED_CAP per (person, team). Rows are only a convenience: the read
    re-checks project access, so nothing here can show a task the person
    cannot open.
    """
    from datetime import timedelta

    from django.db.models import Max
    from django.utils import timezone

    TaskActivity = apps.get_model("origin", "TaskActivity")
    TaskRecent = apps.get_model("origin", "TaskRecent")

    since = timezone.now() - timedelta(days=SEED_DAYS)
    latest = (
        TaskActivity.objects.filter(
            ts_created_at__gte=since,
            actor__isnull=False,
            task__is_deleted=False,
            task__is_init_task=False,
            task__project__isnull=False,
            task__project__is_deleted=False,
        )
        .values("actor_id", "task_id", "task__project__team_id")
        .annotate(last=Max("ts_created_at"))
        .order_by("-last")
    )
    kept: dict = {}
    batch = []
    for row in latest.iterator(chunk_size=2000):
        key = (row["actor_id"], row["task__project__team_id"])
        if kept.get(key, 0) >= SEED_CAP:
            continue
        kept[key] = kept.get(key, 0) + 1
        batch.append(
            TaskRecent(
                user_id=row["actor_id"],
                task_id=row["task_id"],
                team_id=row["task__project__team_id"],
                ts_opened_at=row["last"],
            )
        )
        if len(batch) >= 1000:
            TaskRecent.objects.bulk_create(batch, ignore_conflicts=True)
            batch = []
    if batch:
        TaskRecent.objects.bulk_create(batch, ignore_conflicts=True)


